def derive(lecture):
    for key, src, dst in CHAIN:
        text = (A / src / f'{lecture}.md').read_text()
        for old, new in EDITS[lecture][key]:
            assert text.count(old) == 1, (lecture, key, text.count(old), old[:70])
            text = text.replace(old, new)
        for old, new in GLOBAL_TERMS.get(key, []):
            text = text.replace(old, new)
        (A / dst).mkdir(exist_ok=True)
        (A / dst / f'{lecture}.md').write_text(text)
    return lecture


if __name__ == '__main__':
    for lecture in (sys.argv[1:] or [k for k in MODULE1 if k in EDITS]):
        derive(lecture)
        print('derived', lecture)
